source('R/stile.R');d<-leggi('campioni_modulo1.csv');d$rho<-d$massa_g/d$volume_cm3;out<-'risultati/T00';dir.create(out,recursive=TRUE,showWarnings=FALSE)
verifica('dimensioni del campione',nrow(d)==24&&length(unique(d$stazione))==6&&length(unique(d$affioramento))==2)
verifica('esempio manuale',abs(d$rho[1]-2.68)<1e-12)
salva('T00','F01',ggplot(d,aes(volume_cm3,massa_g,colour=affioramento))+geom_point(size=2.6)+scale_colour_manual(values=geo[1:2])+scale_x_continuous(breaks=c(40,45,50),labels=fmt)+labs(x='Volume (cm³)',y='Massa (g)'))
salva('T00','F02',ggplot(d,aes(stazione,rho,colour=affioramento))+geom_point(size=2.2,position=position_jitter(width=.08,height=0,seed=17))+scale_colour_manual(values=geo[1:2])+scale_y_continuous(labels=fmt)+labs(x='Stazione',y='Densità (g/cm³)'))
s<-aggregate(rho~affioramento,d,mean);salva('T00','F03',ggplot(d,aes(affioramento,rho))+geom_point(colour=geo[1],position=position_jitter(width=.1,height=0,seed=17),size=2)+geom_point(data=s,shape=18,colour=geo[2],size=4)+scale_y_continuous(labels=fmt)+labs(x='Affioramento',y='Densità (g/cm³)'))
a<-data.frame(convenzione=c('Divisore n','Divisore n − 1'),valore=c(sqrt(mean((1:3-2)^2)),sd(1:3)));verifica('convenzioni deviazione standard',abs(a$valore[1]-sqrt(2/3))<1e-12&&a$valore[2]==1)
salva('T00','F04',ggplot(a,aes(convenzione,valore,fill=convenzione))+geom_col(width=.55)+scale_fill_manual(values=geo[1:2])+guides(fill='none')+scale_y_continuous(breaks=c(0,.5,1),labels=fmt)+labs(x=NULL,y='Deviazione standard'))
z<-data.frame(n=seq(10,100,10));cc<-rbind(data.frame(n=z$n,operazioni=z$n,ordine='n'),data.frame(n=z$n,operazioni=z$n^2,ordine='n²'))
salva('T00','F05',ggplot(cc,aes(n,operazioni,colour=ordine))+geom_line(linewidth=.8)+geom_point(size=2)+scale_colour_manual(values=geo[1:2])+scale_x_continuous(breaks=c(10,50,100))+scale_y_log10(breaks=c(10,100,1000,10000),labels=c('10','100','1000','10000'))+labs(x='Dimensione n',y='Conteggio teorico'))
write.csv(s,file.path(out,'medie_affioramenti.csv'),row.names=FALSE)
jsonlite::write_json(list(prima_densita=d$rho[1],media=mean(d$rho),medie=s,media_rapporti=mean(d$rho),rapporto_somme=sum(d$massa_g)/sum(d$volume_cm3),sd_convenzioni=a),file.path(out,'valori.json'),pretty=TRUE,digits=12,auto_unbox=TRUE)
